#include "ota_handler.h"\n #include < esp_log.h>\n #include < esp_matter.h>\n #include < esp_matter_ota.h>\n #include < platform / ESP32 / OTAImageProcessorImpl.h>\n #include < app / clusters / ota - requestor / BDXDownloader.h>\n #include < app / clusters / ota - requestor / DefaultOTARequestor.h>\n #include < app / clusters / ota - requestor / DefaultOTARequestorStorage.h>\n #include < app / clusters / ota - requestor / ExtendedOTARequestorDriver.h>\n\nstatic const char *TAG = "OTA_HANDLER";\n\nusing namespace chip;\nusing namespace chip::OTA;\n\nstatic DefaultOTARequestor gRequestorCore;\nstatic DefaultOTARequestorStorage gRequestorStorage;\nstatic ExtendedOTARequestorDriver gRequestorUser;\nstatic BDXDownloader gDownloader;\nstatic OTAImageProcessorImpl gImageProcessor;\n\nvoid ota_handler_init(void){\n ESP_LOGI(TAG, "Initializing Matter OTA Requestor...");\n\n SetRequestorInstance(&gRequestorCore);\n    \n gRequestorStorage.Init(chip::Server::GetInstance().GetPersistentStorage());\n gRequestorCore.Init(chip::Server::GetInstance(), &gRequestorStorage, &gRequestorUser, &gDownloader);\n\n gImageProcessor.SetOTAImageFile("firmware.bin");\n gImageProcessor.SetOTAImageDownloadContext(&gDownloader);\n    \n gDownloader.SetImageProcessorDelegate(&gImageProcessor);\n gRequestorUser.Init(&gRequestorCore, &gImageProcessor);\n\n ESP_LOGI(TAG, "Matter OTA initialized. Firmware version exposes locally.");\n }\n
